import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { Car, Manufacturer, ManufacturerRating, Rating } from './models';

/** Thin wrapper over the existing JAX-RS API at /api (see ApiPaths.java). */
@Injectable({ providedIn: 'root' })
export class ApiService {
  private readonly http = inject(HttpClient);

  getManufacturers(): Observable<Manufacturer[]> {
    return this.http.get<Manufacturer[]>('/api/manufacturers');
  }

  saveManufacturer(manufacturer: Manufacturer): Observable<Manufacturer> {
    return this.http.post<Manufacturer>('/api/manufacturers', manufacturer);
  }

  deleteManufacturer(id: number): Observable<void> {
    return this.http.delete<void>(`/api/manufacturers/${id}`);
  }

  getAverageRatings(): Observable<ManufacturerRating[]> {
    return this.http.get<ManufacturerRating[]>('/api/manufacturers/ratings');
  }

  getRatings(): Observable<Rating[]> {
    return this.http.get<Rating[]>('/api/ratings');
  }

  saveRating(rating: Rating): Observable<Rating> {
    return this.http.post<Rating>('/api/ratings', rating);
  }

  deleteRating(id: number): Observable<void> {
    return this.http.delete<void>(`/api/ratings/${id}`);
  }

  getCars(): Observable<Car[]> {
    return this.http.get<Car[]>('/api/cars');
  }
}
