import { Component, OnInit, inject } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../api.service';
import { MessageService } from '../message.service';
import { Manufacturer } from '../models';

@Component({
  selector: 'app-manufacturers',
  standalone: true,
  imports: [FormsModule],
  template: `
    <div class="title">
      <h2>Manufacturers</h2>
      <button id="gwt-debug-create-manufacturer" (click)="create()">Create manufacturer</button>
    </div>

    <table id="gwt-debug-manufacturers" class="grid">
      <thead>
        <tr>
          <th>ID</th>
          <th>Name</th>
          <th>Edit</th>
          <th>Delete</th>
        </tr>
      </thead>
      <tbody>
        @for (m of manufacturers; track m.id) {
          <tr>
            <td>{{ m.id }}</td>
            <td>{{ m.name }}</td>
            <td><button (click)="edit(m)">Edit</button></td>
            <td><button (click)="remove(m)">Delete</button></td>
          </tr>
        }
      </tbody>
    </table>

    @if (editorOpen) {
      <div class="overlay">
        <div id="gwt-debug-manufacturer-editor" class="popup">
          <div>
            <label>Name:</label>
            <input id="gwt-debug-manufacturer-input" type="text" [(ngModel)]="editorName" />
          </div>
          <div>
            <button id="gwt-debug-manufacturer-save" (click)="save()">Save</button>
            <button id="gwt-debug-manufacturer-close" (click)="close()">Close</button>
          </div>
        </div>
      </div>
    }
  `,
  styles: [`
    .title { display: flex; justify-content: space-between; align-items: center; }
    table.grid { width: 100%; border-collapse: collapse; margin-top: 20px; }
    th, td { border-bottom: 1px solid #ddd; padding: 6px; text-align: left; }
    .overlay { position: fixed; inset: 0; background: rgba(0, 0, 0, 0.3); display: flex; align-items: center; justify-content: center; }
    .popup { background: #fff; padding: 20px; min-width: 300px; }
    .popup div { margin-bottom: 10px; }
  `],
})
export class ManufacturersComponent implements OnInit {
  private readonly api = inject(ApiService);
  private readonly messages = inject(MessageService);

  manufacturers: Manufacturer[] = [];
  editorOpen = false;
  editorName = '';
  private editing: Manufacturer | null = null;

  ngOnInit(): void {
    this.load();
  }

  create(): void {
    this.editing = null;
    this.editorName = '';
    this.editorOpen = true;
  }

  edit(manufacturer: Manufacturer): void {
    this.editing = manufacturer;
    this.editorName = manufacturer.name;
    this.editorOpen = true;
  }

  close(): void {
    this.editorOpen = false;
  }

  save(): void {
    const body: Manufacturer = { ...(this.editing ?? { id: null, name: '' }), name: this.editorName };
    this.api.saveManufacturer(body).subscribe({
      next: (saved) => {
        // Like the GWT presenter: a new row is appended, an edited row is replaced in place.
        if (this.editing) {
          this.manufacturers = this.manufacturers.map((m) => (m.id === saved.id ? saved : m));
        } else {
          this.manufacturers = [...this.manufacturers, saved];
        }
        this.editorOpen = false;
        this.messages.success('The manufacturer has been saved.');
      },
      error: () => this.messages.error('The manufacturer could not be saved.'),
    });
  }

  remove(manufacturer: Manufacturer): void {
    if (!window.confirm('Are you sure you want to delete ' + manufacturer.name + '?')) {
      return;
    }
    this.api.deleteManufacturer(manufacturer.id!).subscribe({
      next: () => this.load(),
      error: () => this.messages.error('The manufacturer could not be deleted.'),
    });
  }

  private load(done?: () => void): void {
    this.api.getManufacturers().subscribe({
      next: (list) => {
        this.manufacturers = list;
        done?.();
      },
      error: () => this.messages.error('The manufacturers could not be loaded.'),
    });
  }
}
