import { Component, OnInit, inject } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../api.service';
import { MessageService } from '../message.service';
import { Car, Rating } from '../models';

@Component({
  selector: 'app-ratings',
  standalone: true,
  imports: [FormsModule],
  template: `
    <div class="title">
      <h2>Ratings</h2>
      <button id="gwt-debug-ratingCreate" (click)="create()">Create rating</button>
    </div>

    <table id="gwt-debug-ratings" class="grid">
      <thead>
        <tr>
          <th>ID</th>
          <th>Car</th>
          <th>Rating</th>
          <th>Delete</th>
        </tr>
      </thead>
      <tbody>
        @for (r of ratings; track r.id) {
          <tr>
            <td>{{ r.id }}</td>
            <td>{{ carLabel(r.car) }}</td>
            <td>{{ r.rating }}</td>
            <td><button (click)="remove(r)">Delete</button></td>
          </tr>
        }
      </tbody>
    </table>

    @if (editorOpen) {
      <div class="overlay">
        <div class="popup">
          <div>
            <label>Car:</label>
            <select [(ngModel)]="selectedCarId">
              @for (c of cars; track c.id) {
                <option [ngValue]="c.id">{{ carLabel(c) }}</option>
              }
            </select>
          </div>
          <div>
            <label>Your rating:</label>
            <input id="gwt-debug-ratingInput" type="number" maxlength="3" [(ngModel)]="ratingValue" />
          </div>
          <div>
            <button id="gwt-debug-ratingSave" (click)="save()">Save</button>
            <button (click)="close()">Close</button>
          </div>
        </div>
      </div>
    }
  `,
  styles: [`
    .title { display: flex; justify-content: space-between; align-items: center; }
    table.grid { width: 100%; border-collapse: collapse; margin-top: 20px; }
    th, td { border-bottom: 1px solid #ddd; padding: 6px; text-align: left; }
    .overlay { position: fixed; inset: 0; background: rgba(0, 0, 0, 0.3); display: flex; align-items: center; justify-content: center; }
    .popup { background: #fff; padding: 20px; min-width: 300px; }
    .popup div { margin-bottom: 10px; }
  `],
})
export class RatingsComponent implements OnInit {
  private readonly api = inject(ApiService);
  private readonly messages = inject(MessageService);

  ratings: Rating[] = [];
  cars: Car[] = [];
  editorOpen = false;
  selectedCarId: number | null = null;
  ratingValue: number | null = null;

  ngOnInit(): void {
    this.load();
  }

  carLabel(car: Car | null): string {
    if (!car) {
      return '';
    }
    // Ratings can embed a car without its manufacturer; fall back to the cars list.
    const full = this.cars.find((c) => c.id === car.id);
    const manufacturer = car.manufacturer ?? full?.manufacturer ?? null;
    return (manufacturer ? manufacturer.name : '') + '/' + car.model;
  }

  create(): void {
    this.ratingValue = null;
    this.selectedCarId = this.cars.length > 0 ? this.cars[0].id : null;
    this.editorOpen = true;
  }

  close(): void {
    this.editorOpen = false;
  }

  save(): void {
    const car = this.cars.find((c) => c.id === this.selectedCarId) ?? null;
    const body: Rating = { id: null, rating: this.ratingValue, car };
    this.api.saveRating(body).subscribe({
      next: (saved) => {
        // Like the GWT presenter: the new rating is appended to the table.
        this.ratings = [...this.ratings, saved];
        this.editorOpen = false;
        this.messages.success('The rating has been saved.');
      },
      error: () => this.messages.error('The rating could not be saved.'),
    });
  }

  remove(rating: Rating): void {
    if (!window.confirm('Are you sure you want to delete ' + this.carLabel(rating.car) + '?')) {
      return;
    }
    this.api.deleteRating(rating.id!).subscribe({
      next: () => this.load(),
      error: () => this.messages.error('The rating could not be deleted.'),
    });
  }

  private load(done?: () => void): void {
    this.api.getRatings().subscribe({
      next: (list) => {
        this.ratings = list;
        done?.();
      },
      error: () => this.messages.error('The ratings could not be loaded.'),
    });
    this.api.getCars().subscribe({
      next: (list) => (this.cars = list),
      error: () => this.messages.error('The cars could not be loaded.'),
    });
  }
}
